package audit

import "strings"

// NormalizeKind removes surrounding whitespace and lowercases the kind.
func NormalizeKind(kind string) string {
	return strings.ToLower(strings.TrimSpace(kind))
}

func Classify(kind string) string {
	switch kind {
	case "health", "probe":
		return "control"
	default:
		return "data"
	}
}

